CREATE TABLE IF NOT EXISTS branch(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,address VARCHAR(250));
CREATE TABLE IF NOT EXISTS app_user(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(25) NOT NULL CHECK(role IN ('ADMIN','MANAGER','RECEPTIONIST','TECHNICIAN','CUSTOMER')),full_name VARCHAR(100) NOT NULL,is_active BOOLEAN DEFAULT TRUE,failed_attempts INT DEFAULT 0,locked_until TIMESTAMP);
CREATE TABLE IF NOT EXISTS tier(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(25) UNIQUE NOT NULL,min_spending BIGINT NOT NULL CHECK(min_spending>=0),discount_percent INT CHECK(discount_percent BETWEEN 0 AND 50),multiplier DECIMAL(5,2) CHECK(multiplier>0));
CREATE TABLE IF NOT EXISTS customer(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES app_user(id),full_name VARCHAR(100) NOT NULL,phone VARCHAR(15) UNIQUE NOT NULL,email VARCHAR(150),birthday DATE,allergy_note VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS service(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(50) NOT NULL,price BIGINT NOT NULL CHECK(price>=0),duration_min INT NOT NULL CHECK(duration_min BETWEEN 15 AND 480),room_type VARCHAR(20) NOT NULL,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS staff(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT UNIQUE REFERENCES app_user(id),full_name VARCHAR(100) NOT NULL,phone VARCHAR(15) NOT NULL,branch_id BIGINT NOT NULL REFERENCES branch(id),commission_percent INT NOT NULL CHECK(commission_percent BETWEEN 0 AND 100),is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS staff_skill(staff_id BIGINT REFERENCES staff(id),service_id BIGINT REFERENCES service(id),PRIMARY KEY(staff_id,service_id));
CREATE TABLE IF NOT EXISTS room(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,branch_id BIGINT REFERENCES branch(id),room_type VARCHAR(20) NOT NULL,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS work_shift(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staff_id BIGINT REFERENCES staff(id),work_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,CHECK(end_time>start_time),UNIQUE(staff_id,work_date,start_time));
CREATE TABLE IF NOT EXISTS attendance(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staff_id BIGINT REFERENCES staff(id),work_date DATE NOT NULL,check_in TIMESTAMP NOT NULL,check_out TIMESTAMP,UNIQUE(staff_id,work_date));
CREATE TABLE IF NOT EXISTS combo(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,discount_percent INT CHECK(discount_percent BETWEEN 0 AND 80),is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS combo_item(combo_id BIGINT REFERENCES combo(id),service_id BIGINT REFERENCES service(id),PRIMARY KEY(combo_id,service_id));
CREATE TABLE IF NOT EXISTS treatment_package(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,service_id BIGINT REFERENCES service(id),total_sessions INT CHECK(total_sessions>0),price BIGINT CHECK(price>=0),valid_days INT CHECK(valid_days>0),is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS customer_package(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customer(id),package_id BIGINT REFERENCES treatment_package(id),remaining_sessions INT CHECK(remaining_sessions>=0),purchased_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS appointment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customer(id),branch_id BIGINT REFERENCES branch(id),start_at TIMESTAMP NOT NULL,end_at TIMESTAMP NOT NULL,status VARCHAR(20) DEFAULT 'CONFIRMED' CHECK(status IN ('CONFIRMED','CHECKED_IN','IN_PROGRESS','COMPLETED','CANCELLED','NO_SHOW')),note VARCHAR(500),cancel_reason VARCHAR(250),combo_percent INT DEFAULT 0,created_by BIGINT REFERENCES app_user(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS appointment_item(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,appointment_id BIGINT REFERENCES appointment(id),service_id BIGINT REFERENCES service(id),staff_id BIGINT REFERENCES staff(id),room_id BIGINT REFERENCES room(id),start_at TIMESTAMP NOT NULL,end_at TIMESTAMP NOT NULL,price_at_booking BIGINT NOT NULL,customer_package_id BIGINT REFERENCES customer_package(id));
CREATE TABLE IF NOT EXISTS promotion(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,discount_percent INT CHECK(discount_percent BETWEEN 1 AND 80),start_date DATE NOT NULL,end_date DATE NOT NULL,max_uses INT CHECK(max_uses>0),used_count INT DEFAULT 0,min_total BIGINT DEFAULT 0 CHECK(min_total>=0),is_active BOOLEAN DEFAULT TRUE,CHECK(end_date>=start_date));
CREATE TABLE IF NOT EXISTS invoice(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,appointment_id BIGINT UNIQUE REFERENCES appointment(id),customer_id BIGINT REFERENCES customer(id),subtotal BIGINT NOT NULL,package_discount BIGINT DEFAULT 0,combo_discount BIGINT DEFAULT 0,tier_discount BIGINT DEFAULT 0,promo_discount BIGINT DEFAULT 0,point_discount BIGINT DEFAULT 0,total BIGINT NOT NULL CHECK(total>=0),status VARCHAR(20) DEFAULT 'PAID',cashier_id BIGINT REFERENCES app_user(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,description VARCHAR(250));
CREATE TABLE IF NOT EXISTS payment(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,invoice_id BIGINT REFERENCES invoice(id),method VARCHAR(20) CHECK(method IN ('CASH','CARD','TRANSFER','QR')),amount BIGINT NOT NULL CHECK(amount>0),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS loyalty_entry(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customer(id),invoice_id BIGINT REFERENCES invoice(id),entry_type VARCHAR(15) NOT NULL,points INT NOT NULL,remaining_points INT DEFAULT 0 CHECK(remaining_points>=0),expires_at TIMESTAMP,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,sku VARCHAR(40) UNIQUE NOT NULL,unit VARCHAR(20) NOT NULL,sale_price BIGINT CHECK(sale_price>=0),stock_qty INT DEFAULT 0 CHECK(stock_qty>=0),reorder_level INT DEFAULT 0 CHECK(reorder_level>=0),is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS service_product(service_id BIGINT REFERENCES service(id),product_id BIGINT REFERENCES product(id),quantity INT CHECK(quantity>0),PRIMARY KEY(service_id,product_id));
CREATE TABLE IF NOT EXISTS stock_movement(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,product_id BIGINT REFERENCES product(id),quantity INT NOT NULL,reason VARCHAR(250) NOT NULL,appointment_id BIGINT REFERENCES appointment(id),created_by BIGINT REFERENCES app_user(id),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoice_product(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,invoice_id BIGINT REFERENCES invoice(id),product_id BIGINT REFERENCES product(id),quantity INT CHECK(quantity>0),unit_price BIGINT CHECK(unit_price>=0));
CREATE TABLE IF NOT EXISTS commission(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,staff_id BIGINT REFERENCES staff(id),invoice_id BIGINT REFERENCES invoice(id),amount BIGINT CHECK(amount>=0),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(staff_id,invoice_id));
CREATE TABLE IF NOT EXISTS review(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,appointment_id BIGINT UNIQUE REFERENCES appointment(id),customer_id BIGINT REFERENCES customer(id),rating INT CHECK(rating BETWEEN 1 AND 5),comment VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,customer_id BIGINT REFERENCES customer(id),appointment_id BIGINT REFERENCES appointment(id),channel VARCHAR(20) NOT NULL,message VARCHAR(1000) NOT NULL,status VARCHAR(20) DEFAULT 'PENDING',due_at TIMESTAMP NOT NULL,sent_at TIMESTAMP,kind VARCHAR(30),UNIQUE(appointment_id,kind));
CREATE TABLE IF NOT EXISTS audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT REFERENCES app_user(id),action VARCHAR(60),detail VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_item_staff_time ON appointment_item(staff_id,start_at,end_at);
CREATE INDEX IF NOT EXISTS idx_item_room_time ON appointment_item(room_id,start_at,end_at);
CREATE INDEX IF NOT EXISTS idx_invoice_date ON invoice(created_at);
CREATE INDEX IF NOT EXISTS idx_loyalty_customer ON loyalty_entry(customer_id,expires_at);
